#define Z_T4149_INDEX_EMPTY (-1)
#define Z_T4149_INDEX_DELETED (-2)

typedef struct {
    uint8_t alive;
    uint64_t hash;
    z_t59_t key;
    uint32_t value;
} z_t4149_entry_t;

typedef struct z_t4149_t {
    uint64_t capacity;
    uint64_t length;
    uint64_t entries_len;
    uint64_t entries_cap;
    int64_t* indices;
    z_t4149_entry_t* entries;
} z_t4149_t;

static uint64_t z_t4149_hash_key(const z_t59_t* _key);
static uint64_t z_t4149_hash_key(const z_t59_t* _key) {
    return z_siphash_bytes(_key->data, _key->size);
}

static int z_t4149_keys_equal(const z_t59_t* _a, const z_t59_t* _b);
static int z_t4149_keys_equal(const z_t59_t* _a, const z_t59_t* _b) {
    return _a->size == _b->size && memcmp(_a->data, _b->data, _a->size) == 0;
}

static void z_t4149_destroy(z_t4149_t* p);
static void z_t4149_destroy(z_t4149_t* p) {
    if (!p) return;
    for (uint64_t i = 0; i < p->entries_len; i++) {
        if (p->entries[i].alive) {
            z_t59_free(&p->entries[i].key);
        }
    }
    free(p->indices);
    free(p->entries);
    free(p);
}

static z_t4149_t* z_t4149_create(uint64_t _capacity);
static z_t4149_t* z_t4149_create(uint64_t _capacity) {
    z_t4149_t* _this = (z_t4149_t*)z_xmalloc(sizeof(z_t4149_t));
    *_this = (z_t4149_t){0};
    if (_capacity < 8) _capacity = 0;
    /* probing masks with (capacity - 1): round any caller capacity up to
       a power of two */
    if (_capacity & (_capacity - 1)) {
        uint64_t _p2 = 8;
        while (_p2 < _capacity) _p2 <<= 1;
        _capacity = _p2;
    }
    _this->capacity = _capacity;
    _this->entries_cap = _capacity;
    if (_capacity > 0) {
        _this->indices = (int64_t*)z_xmalloc(_capacity * sizeof(int64_t));
        for (uint64_t i = 0; i < _capacity; i++) {
            _this->indices[i] = Z_T4149_INDEX_EMPTY;
        }
        _this->entries = (z_t4149_entry_t*)z_xcalloc(_capacity, sizeof(z_t4149_entry_t));
    }
    return _this;
}

static void z_t4149_grow(z_t4149_t* _this);
static void z_t4149_grow(z_t4149_t* _this) {
    uint64_t old_cap = _this->capacity;
    uint64_t new_cap = old_cap == 0 ? 8 : old_cap * 2;
    z_t4149_entry_t* old_entries = _this->entries;
    uint64_t old_entries_len = _this->entries_len;
    int64_t* new_indices = (int64_t*)z_xmalloc(new_cap * sizeof(int64_t));
    for (uint64_t i = 0; i < new_cap; i++) {
        new_indices[i] = Z_T4149_INDEX_EMPTY;
    }
    z_t4149_entry_t* new_entries = (z_t4149_entry_t*)z_xcalloc(new_cap, sizeof(z_t4149_entry_t));
    uint64_t new_entries_len = 0;
    for (uint64_t i = 0; i < old_entries_len; i++) {
        if (!old_entries[i].alive) continue;
        new_entries[new_entries_len] = old_entries[i];
        uint64_t probe = old_entries[i].hash & (new_cap - 1);
        while (new_indices[probe] != Z_T4149_INDEX_EMPTY) {
            probe = (probe + 1) & (new_cap - 1);
        }
        new_indices[probe] = (int64_t)new_entries_len;
        new_entries_len++;
    }
    free(_this->indices);
    free(old_entries);
    _this->indices = new_indices;
    _this->entries = new_entries;
    _this->capacity = new_cap;
    _this->entries_cap = new_cap;
    _this->entries_len = new_entries_len;
}

static int64_t z_t4149_find(const z_t4149_t* _this, const z_t59_t* _key, uint64_t _hash, int64_t* _slot_out);
static int64_t z_t4149_find(const z_t4149_t* _this, const z_t59_t* _key, uint64_t _hash, int64_t* _slot_out) {
    if (_this->capacity == 0) return -1;
    uint64_t probe = _hash & (_this->capacity - 1);
    for (uint64_t i = 0; i < _this->capacity; i++) {
        int64_t slot = _this->indices[probe];
        if (slot == Z_T4149_INDEX_EMPTY) {
            if (_slot_out) *_slot_out = (int64_t)probe;
            return -1;
        }
        if (slot != Z_T4149_INDEX_DELETED) {
            if (_this->entries[slot].hash == _hash && z_t4149_keys_equal(&_this->entries[slot].key, _key)) {
                if (_slot_out) *_slot_out = (int64_t)probe;
                return slot;
            }
        }
        probe = (probe + 1) & (_this->capacity - 1);
    }
    return -1;
}

static void z_t4149_set(z_t4149_t* _this, z_t59_t _key, uint32_t _val);
